or    %l7, %lo(0x15deade1), %l7
stw %l7, [%i5] 
ld [%i5], %f16

! Initialize running integer counter in register %l4
sethi %hi(0xa800001), %l4
or    %l4, %lo(0xa800001), %l4

! Initialize running FP counter in register %f16
sethi %hi(0x4a000001), %l7
or    %l7, %lo(0x4a000001), %l7
stw %l7, [%i5] 
ld [%i5], %f16

! Initialize FP counter increment value in register %f17 (constant)
sethi %hi(0x3e800000), %l7
or    %l7, %lo(0x3e800000), %l7
stw %l7, [%i5] 
ld [%i5], %f17 

! Initialize LFSR to 0x334f^4
sethi %hi(0x334f), %l0
or    %l0, %lo(0x334f), %l0
mulx  %l0, %l0, %l0
mulx  %l0, %l0, %l0

!-- init shared addrs 10 to 10 ---
stx %g0, [%i2+32]

! use untouched cache-line (offset 4K) in replacement area for sync
sub %i1, %i0, %o5
add %i3, %o5, %o5
sub %o5, -4096, %o5

!-- begin of sync_init ---
or %g0, 1, %l3
or %g0, %l3, %l6
swap [%o5+4], %l6
membar #Sync
sync_init_1_21:
brnz,pt %l3, sync_init_1_21
lduw [%o5+4], %l3 ! delay slot
sync_init_2_21:
lduw [%o5], %l3
sub %l3, 1, %l6
cas [%o5], %l3, %l6
cmp %l3, %l6
bne,pt %xcc, sync_init_2_21
nop
membar #Sync
sync_init_3_21:
lduw [%o5], %l3 ! delay slot
brnz,pt %l3, sync_init_3_21
nop
!-- end of sync_init ---


